/**
 * Surgical regions (module plan, Part A, addition 2: glioma surgery and eloquent cortex): for a region where gliomas
 * are operated on, the cortex that must be spared and the tracts under it, drawn together, with a card on what is
 * mapped there, the deficits after resection and which last. The areas are drawn as named where the atlas has them
 * (the owner's rule, 2026-11-25): HMAT's motor areas, else the Destrieux labels; the tracts are the white-matter
 * section's (HCP-1065), drawn by reference to its files (its manifest is a chunk the tracts and brainstem pages share).
 * Every sentence comes from a paper read in open full text (REG_REFS, and papers the syndrome cards already cite).
 */

/** a drawn area or tract, why it is drawn (from the sources' wording) and the papers that say so */
export interface RegionPart { id: string; why: string; refIds?: string[] }

export interface SurgicalRegion {
  id: string;
  name: string;
  /** the hemisphere drawn (the dominant-side regions: the left) */
  side: Hemi;
  /** the cortex view it belongs to ('insular' cuts the opercula away) */
  view: 'lateral' | 'medial' | 'basal' | 'insular';
  camera: CameraPreset;
  /** Destrieux labels */
  labels: RegionPart[];
  /** the Function selector's areas: HMAT's motor areas (Mayka 2006), and Broca's area as that selector draws it */
  fns: RegionPart[];
  /** the white-matter section's tracts, by its ids and names (a unit test holds them to its manifest); `dashed`: drawn
   * dashed, where its colour is close to another tract's of the region for some colour vision (the palette check's
   * accepted pairs wmOR/wmSLF2 and wmAF/wmCST), so the two are told apart by look */
  tracts: (RegionPart & { name: string; dashed?: boolean })[];
  /** what is mapped there */
  mapped: Claim[];
  /** the usual deficits after resection */
  deficits: Claim[];
  /** which are transient and which last */
  course: Claim[];
  /** how firm the evidence is */
  limits: Claim[];
}

