export const REGION = new Map(REGIONS.map((r) => [r.id, r]));

const WM = WmManifestSchema.parse(wmManifestJson);
const TRACT_IDS = new Set(REGIONS.flatMap((r) => r.tracts.map((t) => t.id)));
/** the white-matter section's tracts the regions draw (their files are that section's) */
export const REGION_TRACTS: ManifestStructure[] = WM.structures.filter((s) => TRACT_IDS.has(s.id));
export const REGION_TRACT = new Map(REGION_TRACTS.map((s) => [s.id, s]));

/** whether `id` is a tract drawn for the region `region` */
export const regionTract = (region: string | null | undefined, id: string | null | undefined): boolean =>
  !!region && !!id && !!REGION.get(region)?.tracts.some((t) => t.id === id);
